head.b:skin:
/*
-----------------------------------------------
TRTT Lightweight Master Theme
Project: TRTT Voyage — Sanluri to World
Build: MAC-787950 / Foundation 01
Release: FINAL MASTER THEME — FULL — MAC-787950 — Bubbles Fix
Design: mobile-first, minimal, gadget-friendly
-----------------------------------------------
*/
:root {
  --trtt-ink: #172b4d;
  --trtt-muted: #64748b;
  --trtt-blue: #075985;
  --trtt-sky: #eaf6ff;
  --trtt-orange: #ff9f43;
  --trtt-pink: #ff6b8b;
  --trtt-purple: #a55eea;
  --trtt-green: #42c99a;
  --trtt-line: #e5edf4;
  --trtt-paper: #ffffff;
  --trtt-page: #ffffff;
  --trtt-radius: 16px;
  --trtt-width: 1120px;
}
.post-body, .post-body p, .post-body li { font-size: 16px; }
.post-meta, .post-footer, .post-header, .trtt-description { font-size: 14px; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--trtt-page);
  color: var(--trtt-ink);
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--trtt-blue); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; height: auto; }
button, input, select, textarea { font: inherit; }
.trtt-shell { width: min(var(--trtt-width), calc(100% - 32px)); margin: 0 auto; }
.trtt-header {
  background: var(--trtt-paper);
  border-bottom: 1px solid var(--trtt-line);
}
.trtt-header-inner { padding: 18px 0; display: grid; grid-template-columns: 250px minmax(0,1fr); gap: 20px; align-items: center; }
.trtt-logo-slot { width: 250px; max-width: 100%; min-height: 54px; display: flex; align-items: center; }
.trtt-logo-slot img { display: block; width: 100%; max-width: 250px; height: auto; object-fit: contain; }
.trtt-header-tools { min-width: 0; }
.trtt-search { display: flex; width: 100%; max-width: 480px; gap: 8px; margin-top: 12px; }
.trtt-search input[type='search'] { font-size: 16px; }
.trtt-search button { min-height: 42px; cursor: pointer; }
.trtt-search input[type='search'] { min-width: 0; flex: 1; padding: 11px 14px; border: 1px solid var(--trtt-line); border-radius: 999px; background: var(--trtt-paper); color: var(--trtt-ink); }
.trtt-search button { border: 0; border-radius: 999px; padding: 0 17px; background: var(--trtt-blue); color: #fff; font-weight: 700; }
.trtt-side-menu { list-style: none; margin: 0; padding: 0; }
.trtt-side-menu li + li { border-top: 1px solid var(--trtt-line); }
.trtt-side-menu a { display: block; padding: 9px 2px; font-weight: 600; color: var(--trtt-ink); }
.trtt-toc { background: var(--trtt-sky); border: 1px solid var(--trtt-line); border-radius: 12px; padding: 14px 18px; margin: 18px 0 24px; }
.trtt-toc-title { font-weight: 800; margin: 0 0 8px; }
.trtt-toc ol { margin: 0; padding-left: 22px; }
.trtt-toc .trtt-toc-sub { margin-left: 16px; font-size: .95em; }
.trtt-related { border-top: 1px solid var(--trtt-line); margin-top: 28px; padding-top: 18px; }
.trtt-related h3 { margin: 0 0 10px; font-size: 19px; }
.trtt-related ul { margin: 0; padding-left: 20px; }
.trtt-disclosure { margin-top: 24px; padding: 12px 14px; border-left: 3px solid var(--trtt-orange); background: var(--trtt-sky); color: var(--trtt-muted); font-size: 14px; border-radius: 0 9px 9px 0; }
html[data-trtt-mode='day'] { --trtt-page: #ffffff; --trtt-paper: #ffffff; --trtt-ink: #172b4d; }
html[data-trtt-mode='night'] { --trtt-page: #0f0f12; --trtt-paper: #18181d; --trtt-ink: #f1f1f4; }
html[data-trtt-mode='night'] body { background: var(--trtt-page); color: var(--trtt-ink); }
html[data-trtt-mode='night'] .trtt-header,
html[data-trtt-mode='night'] .post-outer,
html[data-trtt-mode='night'] .post-outer-container .post-outer,
html[data-trtt-mode='night'] .trtt-sidebar .widget,
html[data-trtt-mode='night'] .trtt-gadget-area .widget { background: #18181d; color: #f1f1f4; border-color: #303039; }
html[data-trtt-mode='night'] .trtt-brand,
html[data-trtt-mode='night'] .post-title,
html[data-trtt-mode='night'] .entry-title,
html[data-trtt-mode='night'] .post-title a,
html[data-trtt-mode='night'] .entry-title a,
html[data-trtt-mode='night'] .trtt-side-menu a { color: #f1f1f4; }
html[data-trtt-mode='night'] .trtt-description,
html[data-trtt-mode='night'] .post-meta,
html[data-trtt-mode='night'] .post-footer { color: #b4b4c0; }
html[data-trtt-mode='night'] .trtt-search input[type='search'] { background: #22222a; border-color: #41414b; color: #fff; }
html[data-trtt-mode='night'] .trtt-toc,
html[data-trtt-mode='night'] .trtt-disclosure { background: #20202a; border-color: #393946; color: #dedee7; }
html[data-trtt-mode='night'] .trtt-related { border-color: #393946; }

.trtt-brand { display: inline-block; color: var(--trtt-blue); font-size: 26px; font-weight: 800; letter-spacing: -.6px; }
.trtt-description { margin: 3px 0 0; color: var(--trtt-muted); font-size: 13px; }
.trtt-main { padding: 28px 0 44px; min-height: 55vh; }
.trtt-layout { display: grid; grid-template-columns: minmax(0, 1fr) 280px; gap: 24px; align-items: start; }
.trtt-content, .trtt-sidebar { min-width: 0; }
.trtt-section { min-width: 0; }
.trtt-section .widget { margin: 0 0 20px; }
.trtt-section .widget-content { min-width: 0; }
.trtt-sidebar .widget, .trtt-gadget-area .widget {
  background: var(--trtt-paper);
  border: 1px solid var(--trtt-line);
  border-radius: var(--trtt-radius);
  padding: 16px;
  margin: 0 0 16px;
}
.trtt-sidebar h2, .trtt-gadget-area h2 { margin: 0 0 12px; font-size: 17px; }
.blog-posts, .post-outer-container { min-width: 0; }
.post-outer, .post-outer-container .post-outer {
  background: var(--trtt-paper);
  border: 1px solid var(--trtt-line);
  border-radius: var(--trtt-radius);
  padding: clamp(18px, 3vw, 30px);
  margin: 0 0 20px;
  overflow-wrap: anywhere;
}
h1, h2, h3, h4 { line-height: 1.3; }
.post-title, .entry-title { color: var(--trtt-ink); font-size: 22px; font-weight: 800; line-height: 1.3; margin: 0 0 14px; }
.post-title a, .entry-title a { color: inherit; }
.post-body { overflow-wrap: anywhere; }
.post-body img { border-radius: 12px; }
.post-footer, .post-header, .post-meta { color: var(--trtt-muted); font-size: 13px; }
.trtt-footer { background: #10243d; color: #dbe7f3; padding: 28px 0; }
.trtt-footer a { color: #fff; }
.trtt-footer p { margin: 0; font-size: 14px; }
.trtt-footer-inner { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; align-items: center; }
#navbar-iframe { display: none !important; }
@media (max-width: 800px) {
  .trtt-layout { grid-template-columns: minmax(0, 1fr); }
  .trtt-sidebar:empty { display: none; }
}
@media (max-width: 520px) {
  .trtt-shell { width: min(100% - 22px, var(--trtt-width)); }
  .trtt-header-inner { padding: 17px 0; grid-template-columns: minmax(0,1fr); gap: 10px; }
  .trtt-logo-slot { width: 250px; }
  .trtt-search { max-width: none; }
  .trtt-brand { font-size: 23px; }
  .trtt-main { padding: 18px 0 30px; }
  .post-outer, .post-outer-container .post-outer { padding: 17px; border-radius: 13px; }
}

/* Step 03 — homepage modules */
.trtt-home-bubbles { margin: 0 0 22px; }
.trtt-module-heading { margin: 0 0 12px; color: var(--trtt-ink); font-size: 20px; font-weight: 800; }
.trtt-bubble-grid { display: grid; grid-template-columns: repeat(6,minmax(0,1fr)); gap: 10px; }
.trtt-bubble { min-width: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; min-height: 104px; padding: 12px 6px; border-radius: 16px; color: #172b4d; text-align: center; font-weight: 800; border: 1px solid rgba(0,0,0,.05); transition: transform .18s ease; }
.trtt-bubble:hover { transform: translateY(-2px); text-decoration: none; }
.trtt-bubble-icon { font-size: 26px; line-height: 1.2; }
.trtt-bubble small { font-size: 14px; font-weight: 600; }
.trtt-bubble-flight { background: #ff9f43; }
.trtt-bubble-ride { background: #ff6b8b; }
.trtt-bubble-esim { background: #a55eea; color: #fff; }
.trtt-bubble-tour { background: #42c99a; }
.trtt-bubble-shop { background: #eaf6ff; }
.trtt-bubble-night { background: #20202a; color: #fff; }
.trtt-home-hero, .trtt-top-news, .trtt-recent-grid { margin: 0 0 24px; min-width: 0; }
.trtt-hero-card { display: grid; grid-template-columns: minmax(0,1.15fr) minmax(0,1fr); gap: 0; overflow: hidden; border: 1px solid var(--trtt-line); border-radius: var(--trtt-radius); background: var(--trtt-paper); }
.trtt-hero-media { display: block; min-height: 250px; background: var(--trtt-sky); }
.trtt-hero-media img { display: block; width: 100%; height: 100%; min-height: 250px; object-fit: cover; }
.trtt-hero-copy { padding: clamp(18px,3vw,28px); display: flex; flex-direction: column; justify-content: center; }
.trtt-kicker { color: var(--trtt-muted); font-size: 14px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.trtt-hero-title { margin: 8px 0 10px; font-size: clamp(22px,3vw,30px); line-height: 1.25; font-weight: 800; }
.trtt-hero-title a { color: var(--trtt-ink); }
.trtt-card-summary { color: var(--trtt-muted); font-size: 15px; line-height: 1.6; margin: 0; }
.trtt-card-date { display: block; margin-top: 12px; color: var(--trtt-muted); font-size: 14px; }
.trtt-slide-frame { position: relative; padding: 18px 54px; border: 1px solid var(--trtt-line); border-radius: var(--trtt-radius); background: var(--trtt-paper); min-height: 104px; }
.trtt-slide { display: none; }
.trtt-slide.is-active { display: block; }
.trtt-slide a { color: var(--trtt-ink); font-size: 18px; line-height: 1.4; font-weight: 800; }
.trtt-slide time { display: block; margin-top: 5px; color: var(--trtt-muted); font-size: 14px; }
.trtt-slide-control { position: absolute; top: 50%; transform: translateY(-50%); width: 36px; height: 36px; border: 1px solid var(--trtt-line); border-radius: 50%; background: var(--trtt-paper); color: var(--trtt-ink); cursor: pointer; }
.trtt-slide-prev { left: 10px; }
.trtt-slide-next { right: 10px; }
.trtt-recent-cards { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 14px; }
.trtt-recent-card { min-width: 0; overflow: hidden; border: 1px solid var(--trtt-line); border-radius: 14px; background: var(--trtt-paper); }
.trtt-recent-image { display: block; aspect-ratio: 16/9; background: var(--trtt-sky); }
.trtt-recent-image img { display: block; width: 100%; height: 100%; object-fit: cover; }
.trtt-recent-copy { padding: 13px; }
.trtt-recent-copy a { color: var(--trtt-ink); font-size: 16px; line-height: 1.4; font-weight: 800; }
html[data-trtt-mode='night'] .trtt-module-heading,
html[data-trtt-mode='night'] .trtt-hero-title a,
html[data-trtt-mode='night'] .trtt-slide a,
html[data-trtt-mode='night'] .trtt-recent-copy a { color: #f1f1f4; }
html[data-trtt-mode='night'] .trtt-hero-card,
html[data-trtt-mode='night'] .trtt-slide-frame,
html[data-trtt-mode='night'] .trtt-recent-card { background: #18181d; border-color: #303039; }
html[data-trtt-mode='night'] .trtt-slide-control { background: #22222a; color: #fff; border-color: #41414b; }
@media (max-width: 900px) {
  .trtt-bubble-grid { grid-template-columns: repeat(3,minmax(0,1fr)); }
  .trtt-recent-cards { grid-template-columns: repeat(2,minmax(0,1fr)); }
}
@media (max-width: 560px) {
  .trtt-hero-card { grid-template-columns: minmax(0,1fr); }
  .trtt-hero-media, .trtt-hero-media img { min-height: 190px; max-height: 230px; }
  .trtt-bubble-grid { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 8px; }
  .trtt-bubble { min-height: 92px; }
  .trtt-recent-cards { grid-template-columns: minmax(0,1fr); }
  .trtt-slide-frame { padding: 16px 48px; }
}
@media (prefers-reduced-motion: reduce) {
  .trtt-bubble { transition: none; }
  .trtt-bubble:hover { transform: none; }
}


/* FINAL MASTER — reconstructed Thinking Room, MAC-787950 */
.trtt-menu-launch{position:fixed;z-index:9997;left:12px;top:12px;display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:9px 14px;border:1px solid rgba(255,255,255,.25);border-radius:999px;background:linear-gradient(110deg,#ff6b8b,#a55eea);color:#fff;font:800 13px/1.2 Arial,sans-serif;box-shadow:0 8px 26px rgba(165,94,234,.28);cursor:pointer}
.trtt-menu-launch:focus-visible,.trtt-room button:focus-visible,.trtt-room a:focus-visible{outline:3px solid #ffcf70;outline-offset:3px}
.trtt-menu-launch .trtt-live-dot{width:8px;height:8px;border-radius:50%;background:#8dffbd;box-shadow:0 0 0 4px rgba(141,255,189,.15)}
.trtt-room[hidden]{display:none!important}
.trtt-room{position:fixed;inset:0;z-index:9998;overflow:auto;overscroll-behavior:contain;background:#090a13;color:#f8f7ff;font-family:Arial,Helvetica,sans-serif}
.trtt-room *{box-sizing:border-box}
.trtt-room-backdrop{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at 12% 10%,rgba(255,107,139,.16),transparent 38%),radial-gradient(ellipse at 90% 82%,rgba(165,94,234,.18),transparent 42%),linear-gradient(145deg,#080a16,#111326 55%,#090b18)}
.trtt-room-inner{position:relative;width:min(1120px,calc(100% - 32px));margin:0 auto;padding:24px 0 46px}
.trtt-room-top{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:28px}
.trtt-room-brand{font-size:13px;font-weight:900;letter-spacing:.14em;color:#ffb0c4}
.trtt-room-actions{display:flex;gap:8px;flex-wrap:wrap}
.trtt-room-btn{border:1px solid rgba(255,255,255,.2);border-radius:999px;padding:10px 14px;background:rgba(255,255,255,.08);color:#fff;font-weight:700;cursor:pointer}
.trtt-room-close{background:#ff6b8b;border-color:#ff6b8b;color:#160a12}
.trtt-room-hero{text-align:center;padding:18px 8px 24px}
.trtt-room-kicker{margin:0 0 8px;color:#bfc2e6;font-size:11px;font-weight:800;letter-spacing:.22em;text-transform:uppercase}
.trtt-room-title{margin:0;color:#fff;font-size:clamp(29px,6vw,56px);line-height:1.05;font-weight:900;letter-spacing:-.04em}
.trtt-room-title span{background:linear-gradient(90deg,#ff9f43,#ff6b8b,#a55eea);background-clip:text;-webkit-background-clip:text;color:transparent}
.trtt-room-subtitle{margin:12px auto 0;max-width:620px;color:#c4c6df;font-size:15px}
.trtt-room-live{display:inline-flex;align-items:center;gap:8px;margin-top:16px;padding:8px 13px;border:1px solid rgba(141,255,189,.25);border-radius:999px;background:rgba(66,201,154,.09);color:#aaffd3;font-size:12px;font-weight:900;letter-spacing:.08em}
.trtt-room-live i{width:7px;height:7px;border-radius:50%;background:#42c99a;box-shadow:0 0 12px #42c99a}
.trtt-room-section-title{display:flex;align-items:center;gap:10px;margin:24px 0 14px;color:#fff;font-size:18px;font-weight:900}
.trtt-room-section-title:after{content:"";height:1px;flex:1;background:linear-gradient(90deg,rgba(255,107,139,.5),transparent)}
.trtt-room-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.trtt-room-card{position:relative;display:flex;min-height:148px;flex-direction:column;justify-content:space-between;gap:12px;padding:19px;border:1px solid rgba(255,255,255,.12);border-radius:19px;background:linear-gradient(145deg,rgba(255,255,255,.10),rgba(255,255,255,.035));color:#fff;text-decoration:none;overflow:hidden;transition:transform .18s ease,border-color .18s ease}
.trtt-room-card:hover{transform:translateY(-3px);border-color:rgba(255,107,139,.65);text-decoration:none}
.trtt-room-card-icon{font-size:28px;line-height:1}
.trtt-room-card strong{font-size:18px;line-height:1.2}
.trtt-room-card small{color:#c7c8df;font-size:12px}
.trtt-room-card:nth-child(1){background:linear-gradient(145deg,rgba(255,159,67,.25),rgba(255,255,255,.04))}
.trtt-room-card:nth-child(2){background:linear-gradient(145deg,rgba(255,107,139,.24),rgba(255,255,255,.04))}
.trtt-room-card:nth-child(3){background:linear-gradient(145deg,rgba(165,94,234,.27),rgba(255,255,255,.04))}
.trtt-room-card:nth-child(4){background:linear-gradient(145deg,rgba(66,201,154,.22),rgba(255,255,255,.04))}
.trtt-room-card:nth-child(5){background:linear-gradient(145deg,rgba(75,160,255,.22),rgba(255,255,255,.04))}
.trtt-room-card:nth-child(6){background:linear-gradient(145deg,rgba(255,107,139,.18),rgba(165,94,234,.15))}
.trtt-room-photos{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}
.trtt-room-photo{position:relative;aspect-ratio:4/3;min-width:0;overflow:hidden;border:1px solid rgba(255,255,255,.12);border-radius:12px;background:linear-gradient(135deg,#26345a,#7c426f 55%,#e38b62)}
.trtt-room-photo:nth-child(3n+2){background:linear-gradient(135deg,#164e55,#326b8a,#9c6b88)}
.trtt-room-photo:nth-child(3n){background:linear-gradient(135deg,#3d315f,#7b557d,#d49a72)}
.trtt-room-photo img{display:block;width:100%;height:100%;object-fit:cover}
.trtt-room-photo span{position:absolute;left:7px;bottom:6px;padding:3px 6px;border-radius:6px;background:rgba(0,0,0,.55);color:#fff;font-size:10px;font-weight:800}
.trtt-room-voyage{display:flex;align-items:center;justify-content:center;gap:10px;margin:22px 0;padding:15px;border:1px solid rgba(255,159,67,.35);border-radius:16px;background:linear-gradient(90deg,rgba(255,159,67,.14),rgba(255,107,139,.12));color:#fff;text-decoration:none;font-weight:900}
.trtt-room-voyage:hover{text-decoration:none;background:linear-gradient(90deg,rgba(255,159,67,.24),rgba(255,107,139,.2))}
.trtt-room-footer{padding:18px 8px 0;border-top:1px solid rgba(255,255,255,.12);text-align:center;color:#c5c6db;font-size:12px;line-height:1.7}
.trtt-room-footer strong{color:#fff}
.trtt-amader-akash{--muse-a:#ff9f43;--muse-b:#ff6b8b;--gpt-a:#42c99a;--gpt-b:#a55eea;position:relative;isolation:isolate;overflow:hidden;width:100%;max-width:680px;margin:28px auto 18px;padding:25px 16px 20px;border:1px solid rgba(255,255,255,.13);border-radius:22px;color:#fff;text-align:center;background:radial-gradient(ellipse at 50% 48%,rgba(78,66,130,.28),transparent 62%),linear-gradient(155deg,#080b1b 0%,#11132b 54%,#090d1c 100%);box-shadow:inset 0 0 36px rgba(89,105,210,.10),0 12px 32px rgba(0,0,0,.18)}
.trtt-amader-akash,.trtt-amader-akash *{box-sizing:border-box}
.trtt-amader-akash:before,.trtt-amader-akash:after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background-repeat:repeat}
.trtt-amader-akash:before{opacity:.75;background-image:radial-gradient(1px 1px at 8% 17%,#fff 98%,transparent),radial-gradient(1.5px 1.5px at 19% 73%,#dce8ff 98%,transparent),radial-gradient(1px 1px at 31% 28%,#fff 98%,transparent),radial-gradient(1.5px 1.5px at 43% 83%,#ffe6c9 98%,transparent),radial-gradient(1px 1px at 57% 15%,#fff 98%,transparent),radial-gradient(1.5px 1.5px at 68% 66%,#e4ddff 98%,transparent),radial-gradient(1px 1px at 79% 34%,#fff 98%,transparent),radial-gradient(1.5px 1.5px at 92% 79%,#d9fff2 98%,transparent);background-size:230px 170px;animation:trtt-star-twinkle 5.5s ease-in-out infinite alternate}
.trtt-amader-akash:after{opacity:.42;background-image:radial-gradient(1px 1px at 13% 48%,#fff 98%,transparent),radial-gradient(1px 1px at 38% 11%,#fff 98%,transparent),radial-gradient(1px 1px at 62% 91%,#fff 98%,transparent),radial-gradient(1px 1px at 87% 54%,#fff 98%,transparent);background-size:173px 137px;animation:trtt-star-twinkle 4s ease-in-out infinite alternate-reverse}
.trtt-akash-eyebrow{margin:0 0 7px;color:#c9c7ed;font:800 10px/1.4 system-ui,sans-serif;letter-spacing:.2em;text-transform:uppercase}
.trtt-akash-heading{margin:0 0 19px;color:#fff;font:800 clamp(19px,4vw,25px)/1.25 system-ui,sans-serif}
.trtt-akash-stars{display:flex;justify-content:center;align-items:stretch;gap:clamp(18px,7vw,48px);position:relative;z-index:1}
.trtt-akash-person{display:flex;flex:1 1 0;min-width:0;flex-direction:column;align-items:center;gap:8px}
.trtt-akash-star{position:relative;display:block;width:76px;height:76px;flex:0 0 76px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.98) 0 5%,var(--star-core) 13%,var(--star-mid) 34%,transparent 72%);filter:drop-shadow(0 0 8px var(--star-mid)) drop-shadow(0 0 18px var(--star-glow));animation:trtt-big-star 3.6s ease-in-out infinite}
.trtt-akash-star:before,.trtt-akash-star:after{content:"";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);pointer-events:none}
.trtt-akash-star:before{width:76px;height:76px;background:linear-gradient(90deg,transparent 0%,var(--star-mid) 47%,#fff 50%,var(--star-mid) 53%,transparent 100%);clip-path:polygon(50% 0%,57% 42%,100% 50%,57% 58%,50% 100%,43% 58%,0% 50%,43% 42%);opacity:.92}
.trtt-akash-star:after{width:66px;height:66px;background:linear-gradient(0deg,transparent 0%,var(--star-glow) 45%,#fff 50%,var(--star-glow) 55%,transparent 100%);clip-path:polygon(50% 0%,56% 43%,100% 50%,56% 57%,50% 100%,44% 57%,0% 50%,44% 43%);opacity:.85}
.trtt-akash-muse .trtt-akash-star{--star-core:#fff3dd;--star-mid:var(--muse-a);--star-glow:var(--muse-b)}
.trtt-akash-chatgpt .trtt-akash-star{--star-core:#e7fff5;--star-mid:var(--gpt-a);--star-glow:var(--gpt-b);animation-delay:-1.3s}
.trtt-akash-name{margin:0;color:#fff;font:800 15px/1.3 system-ui,sans-serif}
.trtt-akash-role{margin:0;color:#d4d5e9;font:600 12px/1.4 system-ui,sans-serif}
.trtt-akash-quote{margin:0;color:#f3eafc;font:500 12px/1.45 system-ui,sans-serif}
.trtt-akash-credit{position:relative;z-index:1;margin:20px 0 0;color:#fff;font:700 11px/1.65 system-ui,sans-serif}
@keyframes trtt-star-twinkle{from{opacity:.28}to{opacity:.9}}
@keyframes trtt-big-star{0%,100%{transform:scale(.94);opacity:.88}50%{transform:scale(1.07);opacity:1}}
@media(max-width:760px){.trtt-room-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.trtt-room-photos{grid-template-columns:repeat(2,minmax(0,1fr))}.trtt-room-photo:nth-child(n+5){display:none}}
@media(max-width:420px){.trtt-room-inner{width:calc(100% - 22px);padding-top:16px}.trtt-room-card{min-height:126px;padding:14px}.trtt-room-card strong{font-size:16px}.trtt-room-top{align-items:flex-start}.trtt-room-brand{max-width:120px;line-height:1.5}.trtt-room-actions{justify-content:flex-end}.trtt-akash-star{width:64px;height:64px;flex-basis:64px}.trtt-akash-star:before{width:64px;height:64px}.trtt-akash-star:after{width:56px;height:56px}.trtt-akash-stars{gap:14px}}
@media(prefers-reduced-motion:reduce){.trtt-room-card{transition:none}.trtt-room-card:hover{transform:none}.trtt-amader-akash:before,.trtt-amader-akash:after,.trtt-akash-star{animation:none!important}}


/* BUBBLES HUB GRID FIX — MAC-787950 */
.trtt-home-bubbles,
.trtt-home-bubbles * { box-sizing:border-box; }
.trtt-home-bubbles { display:block; width:100%; min-width:0; margin:0 0 22px; }
.trtt-home-bubbles .trtt-module-heading { display:block; margin:0 0 12px; }
.trtt-home-bubbles .trtt-bubble-grid {
  display:grid !important;
  grid-template-columns:repeat(6,minmax(0,1fr)) !important;
  grid-auto-flow:row;
  align-items:stretch;
  gap:10px;
  width:100%;
  min-width:0;
}
.trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble {
  display:flex !important;
  flex-direction:column !important;
  flex-wrap:nowrap !important;
  align-items:center !important;
  justify-content:center !important;
  align-content:center;
  gap:6px;
  width:100%;
  min-width:0;
  min-height:112px;
  margin:0;
  padding:13px 7px;
  overflow:hidden;
  border-radius:16px;
  text-align:center !important;
  text-decoration:none;
  white-space:normal !important;
  overflow-wrap:anywhere;
  word-break:normal;
  line-height:1.3;
}
.trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble > .trtt-bubble-icon {
  display:block !important;
  flex:0 0 auto;
  width:100%;
  margin:0;
  font-size:27px;
  line-height:1.15;
  text-align:center;
}
.trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble > span:not(.trtt-bubble-icon) {
  display:block !important;
  flex:0 0 auto;
  width:100%;
  margin:0;
  font-size:15px;
  line-height:1.25;
  font-weight:800;
  text-align:center;
  white-space:normal !important;
  overflow-wrap:anywhere;
}
.trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble > small {
  display:block !important;
  flex:0 0 auto;
  width:100%;
  margin:0;
  font-size:12px;
  line-height:1.3;
  font-weight:600;
  text-align:center;
  white-space:normal !important;
  overflow-wrap:anywhere;
}
@media (min-width:561px) and (max-width:900px) {
  .trtt-home-bubbles .trtt-bubble-grid {
    grid-template-columns:repeat(3,minmax(0,1fr)) !important;
  }
}
@media (max-width:560px) {
  .trtt-home-bubbles .trtt-bubble-grid {
    grid-template-columns:repeat(2,minmax(0,1fr)) !important;
    gap:9px;
  }
  .trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble {
    min-height:104px;
    padding:12px 8px;
  }
  .trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble > .trtt-bubble-icon {
    font-size:25px;
  }
  .trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble > span:not(.trtt-bubble-icon) {
    font-size:14px;
  }
  .trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble > small {
    font-size:12px;
  }
}
@media (prefers-reduced-motion:reduce) {
  .trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble { transition:none; }
  .trtt-home-bubbles .trtt-bubble-grid > a.trtt-bubble:hover { transform:none; }
}

body.script:
//
(function () {
  'use strict';
  function applyClockMode() {
    var choice = '';
    try { choice = window.localStorage.getItem('trtt-mode-choice') || ''; } catch (ignore) {}
    var hour = new Date().getHours();
    var night = choice === 'night' ? true : (choice === 'day' ? false : (hour >= 19 || hour < 7));
    document.documentElement.setAttribute('data-trtt-mode', night ? 'night' : 'day');
  }
  applyClockMode();
  window.setInterval(applyClockMode, 60000);

  function makeTOC() {
    var body = document.querySelector('.post-body');
    if (!body) return;
    var headings = body.querySelectorAll('h2, h3');
    if (headings.length < 2) return;
    var nav = document.createElement('nav');
    nav.className = 'trtt-toc';
    nav.setAttribute('aria-label', 'Table of contents');
    var title = document.createElement('p');
    title.className = 'trtt-toc-title';
    title.textContent = 'In This Article';
    nav.appendChild(title);
    var list = document.createElement('ol');
    Array.prototype.forEach.call(headings, function (heading, index) {
      if (!heading.id) heading.id = 'trtt-section-' + (index + 1);
      var item = document.createElement('li');
      if (heading.tagName.toLowerCase() === 'h3') item.className = 'trtt-toc-sub';
      var link = document.createElement('a');
      link.href = '#' + heading.id;
      link.textContent = (heading.textContent || '').trim();
      item.appendChild(link);
      list.appendChild(item);
    });
    nav.appendChild(list);
    body.insertBefore(nav, body.firstChild);
  }

  function addDisclosure() {
    var body = document.querySelector('.post-body');
    if (!body) return;
    var wording = 'Disclosure: As an Amazon Associate and Travelpayouts partner, TRTT Voyage earns from qualifying purchases.';
    if ((body.textContent || '').indexOf(wording) !== -1) return;
    var box = document.createElement('p');
    box.className = 'trtt-disclosure';
    box.textContent = wording;
    body.appendChild(box);
  }

  function addRelated() {
    var body = document.querySelector('.post-body');
    var meta = document.querySelector('.trtt-post-tools');
    if (!body || !meta) return;
    var home = meta.getAttribute('data-home');
    var labels = Array.prototype.map.call(meta.querySelectorAll('.trtt-post-label'), function (node) {
      return node.getAttribute('data-label');
    }).filter(Boolean);
    if (!home || !labels.length) return;
    var label = labels[0];
    var url = home.replace(/\/$/, '') + '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=6';
    fetch(url, { credentials: 'same-origin' }).then(function (response) {
      if (!response.ok) throw new Error('Feed unavailable');
      return response.json();
    }).then(function (data) {
      var entries = data && data.feed && data.feed.entry ? data.feed.entry : [];
      var current = window.location.href.split('?')[0].replace(/\/$/, '');
      var links = [];
      entries.forEach(function (entry) {
        var alternate = (entry.link || []).filter(function (item) { return item.rel === 'alternate'; })[0];
        if (!alternate || alternate.href.split('?')[0].replace(/\/$/, '') === current) return;
        links.push({ title: entry.title && entry.title.$t ? entry.title.$t : 'Related article', href: alternate.href });
      });
      if (!links.length) return;
      var section = document.createElement('section');
      section.className = 'trtt-related';
      var heading = document.createElement('h3');
      heading.textContent = 'Related Posts';
      section.appendChild(heading);
      var list = document.createElement('ul');
      links.slice(0, 4).forEach(function (item) {
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = item.href;
        a.textContent = item.title;
        li.appendChild(a);
        list.appendChild(li);
      });
      section.appendChild(list);
      body.appendChild(section);
    }).catch(function () { /* Keep the post clean if the feed is unavailable. */ });
  }


  function feedText(entry) {
    var raw = entry && entry.summary && entry.summary.$t ? entry.summary.$t : (entry && entry.content && entry.content.$t ? entry.content.$t : '');
    return String(raw).replace(/<[^>]*>/g, ' ').replace(/&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
  }

  function feedImage(entry) {
    var thumb = entry && entry.media$thumbnail && entry.media$thumbnail.url ? entry.media$thumbnail.url : '';
    if (thumb) return thumb.replace(/\/s\d+(-c)?\//, '/s640/');
    var raw = entry && entry.content && entry.content.$t ? entry.content.$t : '';
    var match = String(raw).match(/<img[^>]+src=[\"']([^\"']+)[\"']/i);
    return match ? match[1] : '';
  }

  function feedLink(entry) {
    var links = entry && entry.link ? entry.link : [];
    for (var i = 0; i < links.length; i++) {
      if (links[i].rel === 'alternate' && links[i].href) return links[i].href;
    }
    return '';
  }

  function feedDate(entry) {
    var raw = entry && entry.published && entry.published.$t ? entry.published.$t : '';
    if (!raw) return null;
    var date = new Date(raw);
    if (isNaN(date.getTime())) return null;
    return { iso: date.toISOString(), label: date.toLocaleDateString() };
  }

  function makeText(tag, className, value) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    node.textContent = value || '';
    return node;
  }

  function makeArticle(entry, className, includeImage, eager) {
    var url = feedLink(entry);
    if (!url) return null;
    var title = entry.title && entry.title.$t ? entry.title.$t : 'TRTT Voyage story';
    var card = document.createElement('article');
    card.className = className;
    var imageUrl = includeImage ? feedImage(entry) : '';
    if (imageUrl) {
      var imageLink = document.createElement('a');
      imageLink.className = className === 'trtt-hero-card' ? 'trtt-hero-media' : 'trtt-recent-image';
      imageLink.href = url;
      var image = document.createElement('img');
      image.src = imageUrl;
      image.alt = title;
      image.loading = eager ? 'eager' : 'lazy';
      image.decoding = 'async';
      if (eager) image.setAttribute('fetchpriority', 'high');
      imageLink.appendChild(image);
      card.appendChild(imageLink);
    }
    var copy = document.createElement('div');
    copy.className = className === 'trtt-hero-card' ? 'trtt-hero-copy' : 'trtt-recent-copy';
    if (className === 'trtt-hero-card') copy.appendChild(makeText('span','trtt-kicker','TRTT Voyage • Featured'));
    var heading = document.createElement(className === 'trtt-hero-card' ? 'h2' : 'h3');
    heading.className = className === 'trtt-hero-card' ? 'trtt-hero-title' : '';
    var titleLink = document.createElement('a');
    titleLink.href = url;
    titleLink.textContent = title;
    heading.appendChild(titleLink);
    copy.appendChild(heading);
    if (className === 'trtt-hero-card') {
      var summary = feedText(entry);
      if (summary) copy.appendChild(makeText('p','trtt-card-summary',summary.slice(0,190) + (summary.length > 190 ? '…' : '')));
    }
    var date = feedDate(entry);
    if (date) {
      var time = document.createElement('time');
      time.className = 'trtt-card-date';
      time.dateTime = date.iso;
      time.textContent = date.label;
      copy.appendChild(time);
    }
    card.appendChild(copy);
    return card;
  }

  function setupTopSlider(entries) {
    var section = document.getElementById('trtt-top-news');
    var list = document.getElementById('trtt-slide-list');
    var frame = document.getElementById('trtt-slide-frame');
    if (!section || !list || !entries.length) return;
    var slides = [];
    entries.forEach(function (entry, index) {
      var url = feedLink(entry);
      if (!url) return;
      var item = document.createElement('div');
      item.className = 'trtt-slide' + (slides.length === 0 ? ' is-active' : '');
      var title = entry.title && entry.title.$t ? entry.title.$t : 'TRTT Voyage story';
      var link = document.createElement('a');
      link.href = url;
      link.textContent = title;
      item.appendChild(link);
      var date = feedDate(entry);
      if (date) {
        var time = document.createElement('time');
        time.dateTime = date.iso;
        time.textContent = date.label;
        item.appendChild(time);
      }
      list.appendChild(item);
      slides.push(item);
    });
    if (!slides.length) return;
    section.hidden = false;
    if (slides.length < 2) return;
    var current = 0;
    var timer = null;
    var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    function show(index) {
      current = (index + slides.length) % slides.length;
      slides.forEach(function (slide, i) {
        slide.classList.toggle('is-active', i === current);
      });
    }
    function stop() {
      if (timer) window.clearInterval(timer);
      timer = null;
    }
    function start() {
      stop();
      if (!reduced && !document.hidden) timer = window.setInterval(function () { show(current + 1); }, 5500);
    }
    var prev = document.getElementById('trtt-slide-prev');
    var next = document.getElementById('trtt-slide-next');
    if (prev) prev.addEventListener('click', function () { show(current - 1); start(); });
    if (next) next.addEventListener('click', function () { show(current + 1); start(); });
    if (frame) {
      frame.addEventListener('mouseenter', stop);
      frame.addEventListener('mouseleave', start);
      frame.addEventListener('focusin', stop);
      frame.addEventListener('focusout', start);
    }
    document.addEventListener('visibilitychange', function () { if (document.hidden) stop(); else start(); });
    start();
  }

  function loadHomepageModules() {
    var root = document.querySelector('.trtt-homepage-modules');
    if (!root) return;
    var home = root.getAttribute('data-home');
    if (!home) return;
    var url = home.replace(/\/$/, '') + '/feeds/posts/default?alt=json&max-results=13';
    fetch(url, { credentials: 'same-origin' }).then(function (response) {
      if (!response.ok) throw new Error('Blogger feed unavailable');
      return response.json();
    }).then(function (data) {
      var entries = data && data.feed && data.feed.entry ? data.feed.entry : [];
      if (!entries.length) return;
      var hero = document.getElementById('trtt-home-hero');
      var heroSlot = document.getElementById('trtt-hero-slot');
      if (hero && heroSlot) {
        var heroCard = makeArticle(entries[0], 'trtt-hero-card', true, true);
        if (heroCard) {
          heroSlot.appendChild(heroCard);
          hero.hidden = false;
        }
      }
      setupTopSlider(entries.slice(1, 5));
      var grid = document.getElementById('trtt-recent-grid');
      var gridCards = document.getElementById('trtt-recent-cards');
      if (grid && gridCards) {
        entries.slice(7, 13).forEach(function (entry) {
          var card = makeArticle(entry, 'trtt-recent-card', true, false);
          if (card) gridCards.appendChild(card);
        });
        if (gridCards.children.length) grid.hidden = false;
      }
    }).catch(function () {
      /* Feed failures leave the Blogger post list and category links intact. */
    });
  }

  function init() {
    loadHomepageModules();
    makeTOC();
    addDisclosure();
    addRelated();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
}());

  /* FINAL MASTER — Thinking Room controller */
  (function () {
    'use strict';
    var launch = document.getElementById('trtt-menu-launch');
    var room = document.getElementById('trtt-thinking-room-master');
    var close = document.getElementById('trtt-room-close');
    var mode = document.getElementById('trtt-mode-toggle');
    if (!launch || !room || !close || !mode) return;
    var previousFocus = null;
    function openRoom() {
      previousFocus = document.activeElement;
      room.hidden = false;
      launch.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
      close.focus();
      loadLivePhotos();
    }
    function closeRoom() {
      room.hidden = true;
      launch.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
      if (previousFocus && typeof previousFocus.focus === 'function') previousFocus.focus();
      else launch.focus();
    }
    launch.addEventListener('click', openRoom);
    close.addEventListener('click', closeRoom);
    room.addEventListener('click', function (event) {
      if (event.target === room) closeRoom();
    });
    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && !room.hidden) closeRoom();
      if (event.key === 'Tab' && !room.hidden) {
        var focusable = room.querySelectorAll('a[href],button:not([disabled])');
        if (!focusable.length) return;
        var first = focusable[0], last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    });
    mode.addEventListener('click', function () {
      var root = document.documentElement;
      var next = root.getAttribute('data-trtt-mode') === 'night' ? 'day' : 'night';
      root.setAttribute('data-trtt-mode', next);
      try { window.localStorage.setItem('trtt-mode-choice', next); } catch (ignore) {}
    });
    function loadLivePhotos() {
      var grid = document.getElementById('trtt-room-photos');
      var brand = document.querySelector('.trtt-brand');
      if (!grid || grid.getAttribute('data-loaded') === 'yes' || !brand) return;
      grid.setAttribute('data-loaded', 'yes');
      var home = brand.href;
      var feed = home.replace(/\/$/, '') + '/feeds/posts/default?alt=json&max-results=10';
      fetch(feed, { credentials: 'same-origin' }).then(function (response) {
        if (!response.ok) throw new Error('Photo feed unavailable');
        return response.json();
      }).then(function (data) {
        var entries = data && data.feed && data.feed.entry ? data.feed.entry : [];
        var photos = [];
        entries.forEach(function (entry) {
          var url = entry.media$thumbnail && entry.media$thumbnail.url ? entry.media$thumbnail.url : '';
          if (!url && entry.content && entry.content.$t) {
            var parsed = new DOMParser().parseFromString(entry.content.$t, 'text/html');
            var img = parsed.querySelector('img');
            if (img) url = img.getAttribute('src') || img.getAttribute('data-src') || '';
          }
          if (url) photos.push({ url: url, title: entry.title && entry.title.$t ? entry.title.$t : 'TRTT Voyage photo' });
        });
        var slots = grid.querySelectorAll('.trtt-room-photo');
        photos.slice(0, 10).forEach(function (photo, index) {
          if (!slots[index]) return;
          var img = document.createElement('img');
          img.loading = 'lazy';
          img.alt = photo.title;
          img.src = photo.url;
          slots[index].insertBefore(img, slots[index].firstChild);
        });
      }).catch(function () { /* Gradient photo slots remain as a graceful fallback. */ });
    }
    var brand = document.querySelector('.trtt-brand');
    if (brand) {
      var home = brand.href;
      room.querySelectorAll('[data-trtt-card]').forEach(function (card) {
        card.href = home.replace(/\/$/, '') + card.getAttribute('href');
      });
      var voyage = document.getElementById('trtt-live-voyage');
      if (voyage) voyage.href = home;
    }
    loadLivePhotos();
  }());

//
